function bevRoleSelect(k,label,hint,cur){const list=bevPeople();if(cur?.personnelId&&!list.some(p=>p.id===cur.personnelId))list.unshift({id:cur.personnelId,name:cur.name||cur.personnelId});return `<div class="field"><label for="v1012BevRole_${k}">${E(label)}</label><select id="v1012BevRole_${k}" data-no-placeholder="1"><option value="">انتخاب نشده</option>${list.map(p=>`<option value="${E(p.id)}" ${cur?.personnelId===p.id?'selected':''}>${E(p.name)}</option>`).join('')}</select><small class="muted">${E(hint)}</small></div>`}
// Roles the user changed on the desktop form (an untouched select never overwrites another user's choice).
function bevReadRoles(base){const out={},key=p=>`${S(p?.personnelId)}|${S(p?.name)}`;for(const k of BEV().ROLE_KEYS){const el=document.getElementById(`v1012BevRole_${k}`);if(!el)continue;const id=S(el.value),cur=base?.[k]||null,p=id?(cur?.personnelId===id?cur:{personnelId:id,name:bevPeople().find(x=>x.id===id)?.name||id}):null;if(key(p)!==key(cur))out[k]=p}return Object.keys(out).length?out:undefined}
function bevEntry(inModal=false){if(!BEV())return '<div class="card empty" role="alert">ماژول مشترک کنترل نوشابه بارگذاری نشد؛ صفحه را بروزرسانی کنید.</div>';const tools=`<div class="v1012-actions"><button type="button" class="btn" onclick="RayoInventoryV1012.bevPrint()">🖨 فرم A5 این تاریخ</button><button type="button" class="btn" onclick="RayoInventoryV1012.bevSettings()">تنظیم اقلام</button></div>`;
 if(!bevItems().length)return `<div class="card"><div class="hint">هنوز نوشیدنی برای کنترل روزانه انتخاب نشده است. <button type="button" class="btn btn-primary btn-sm" onclick="RayoInventoryV1012.bevSettings()">انتخاب اقلام</button></div></div>`;
 if(bevMobile())return bevMobileForm(inModal?'':BEV_TITLE)+(inModal?'':`<div class="card">${tools}</div>`);
 const date=ui.bevDate||bevToday(),rec=bevRecord(date),items=bevItems(),line=id=>A(rec?.lines).find(l=>l.ingredientId===id)||null,roles=BEV().rolesOf(rec),legacy=[rec?.counters?.morning&&`صبح: ${rec.counters.morning}`,rec?.counters?.night&&`شب: ${rec.counters.night}`].filter(Boolean).join(' | ');
 ui.bevBase={date,roles,lines:Object.fromEntries(items.map(it=>{const l=line(it.id);return [it.id,{fp:BEV().fingerprint(l),line:l}]}))};
 return `<form class="card" onsubmit="event.preventDefault();RayoInventoryV1012.bevSave()"><fieldset id="v1012BevFields" style="border:0;padding:0;min-width:0"><div class="section-head"><div><h2>${BEV_TITLE}</h2><p class="muted">خانه خالی یعنی «وارد نشده» و صفر حساب نمی‌شود؛ اگر کالایی نیست «۰» بنویسید. ورودی روز = مجموع شارژ هر دو یخچال. فروش آخرین عددی است که وارد می‌شود. ستون‌های محاسباتی قابل ویرایش نیستند.</p></div>${tools}</div>
 <div class="form-grid"><div class="field"><label for="v1012BevDate">تاریخ کاری *</label><input id="v1012BevDate" data-jalali="1" value="${E(date)}" onchange="RayoInventoryV1012.bevDate(this.value)"></div>${BEV().ROLES.map(([k,l,h])=>bevRoleSelect(k,l,h,roles[k])).join('')}</div>
 <p class="hint">شمارش صبح فردا باید با مانده‌ای که انباردار امشب از شمارنده شب تحویل می‌گیرد برابر باشد؛ هر اختلاف «مغایرت شبانه» است.${legacy?`<br>شمارنده‌های ثبت‌شده در فرم قدیمی: ${E(legacy)}`:''}</p>
 ${rec?`<p class="hint">برای این تاریخ اطلاعات ثبت شده است${rec.source==='staff'&&rec.createdByName?` — اولین ثبت پرسنل: ${E(rec.createdByName)}`:''} (${E(rec.updatedBy||rec.createdBy||'')} — ${E(S(rec.updatedAt||rec.createdAt).slice(0,16).replace('T',' '))}). تغییر هر ردیف ثبت‌شده پس از تأیید ذخیره می‌شود و نسخه قبلی در تاریخچه همان رکورد می‌ماند.${rec.notes?`<br>توضیح قدیمی فرم: ${E(rec.notes)}`:''}</p>`:''}
 <div class="table-wrap"><table class="data-table v1012-bev-table" data-pagination="native"><thead><tr><th rowspan="2">نوشیدنی</th><th colspan="2">شمارش صبح</th><th rowspan="2">ورودی روز</th><th rowspan="2">خروج غیر فروش</th><th colspan="2">مانده شب</th><th rowspan="2">فروش</th><th rowspan="2">مانده مورد انتظار شب</th><th rowspan="2">مغایرت روز<br><small>(+ کسری)</small></th><th rowspan="2">مغایرت شبانه<br><small>(− کاهش)</small></th></tr><tr><th>بالا</th><th>پایین</th><th>بالا</th><th>پایین</th></tr></thead><tbody>${items.map((it,i)=>{const l=line(it.id),v=BEV().formValues(l),m=BEV().values(l),who=[BEV().byText(l?.morningCountedBy,'صبح'),BEV().byText(l?.nightCountedBy,'شب')].filter(Boolean).join(' | '),cells=cols=>cols.map(([f,lb])=>`<td>${bevInput(f,v[f],i,`${it.name} ${lb}`)}</td>`).join('');return `<tr data-bev-item="${E(it.id)}" data-bev-index="${i}"><td rowspan="2"><b>${E(it.name)}</b>${who?`<br><small class="muted">${E(who)}</small>`:''}${m.morningSplit===false||m.nightSplit===false?`<br><small class="muted">مقدار تاریخی بدون تفکیک: ${m.morningSplit===false?`صبح ${F(m.morning,0)} `:''}${m.nightSplit===false?`شب ${F(m.night,0)}`:''}</small>`:''}</td>${cells(BEV_COLS)}${cells(BEV_NIGHT)}${cells(BEV_SALES)}<td data-bev-out="expectedNight"></td><td data-bev-out="daily"></td><td data-bev-out="overnight"></td></tr><tr class="v1012-bev-reason-row"><td colspan="10"><div class="v1012-bev-reasons"><label>علت خروج غیر فروش ${bevInput('nonSaleReason',v.nonSaleReason,i,`${it.name} علت خروج غیر فروش`,true)}</label><label>علت مغایرت ${bevInput('varianceNote',v.varianceNote,i,`${it.name} علت مغایرت`,true)}</label></div></td></tr>`}).join('')}</tbody><tfoot><tr><th colspan="9">جمع ردیف‌های قابل محاسبه</th><th data-bev-total="daily"></th><th data-bev-total="overnight"></th></tr></tfoot></table></div>
 <div class="v1012-form-actions"><button type="submit" class="btn btn-primary" data-v1012-bev-action>${rec?'ذخیره تغییرات':'ذخیره فرم روز'}</button>${rec?`<button type="button" class="btn btn-danger" data-v1012-bev-action onclick="RayoInventoryV1012.bevVoid()">ابطال فرم این تاریخ</button>`:''}</div><p id="v1012BevStatus" role="status"></p>
 </fieldset></form>`}
function bevRowRaw(i){const out={};document.querySelectorAll(`[data-bev-row="${i}"]`).forEach(x=>out[x.dataset.bevField]=x.value);return out}
function bevRowHint(i){const row=document.querySelector(`[data-bev-index="${i}"]`);if(!row)return;const id=row.dataset.bevItem,date=ui.bevBase?.date||ui.bevDate||bevToday(),{values,invalid}=BEV().read(bevRowRaw(i)),bad=invalid.some(f=>f!=='nonSaleReason'),base=ui.bevBase?.lines?.[id]?.line||{},m=bevLineMetrics({...base,...values,formulaVersion:BEV().FORMULA},bevPrevLine(date,id));
 document.querySelectorAll(`[data-bev-row="${i}"]`).forEach(x=>x.setAttribute('aria-invalid',invalid.includes(x.dataset.bevField)?'true':'false'));
 const cells={expectedNight:[m.expectedNight,v=>F(v,0),()=>'',m.missingExpected],daily:[m.daily,bevFmt,bevCls,m.missingDaily],overnight:[m.overnight,bevFmt,bevClsNight,m.missingOvernight]};
 for(const [k,[v,fmt,cls,missing]] of Object.entries(cells)){const c=row.querySelector(`[data-bev-out="${k}"]`);if(!c)continue;c.textContent=bad?'نامعتبر':v===null?'قابل محاسبه نیست':fmt(v);c.title=!bad&&v===null?`وارد نشده: ${missing.join('، ')}`:'';c.className=bad?'v1012-negative':v===null?'muted':cls(v);c.dataset.v=bad||v===null?'':String(v)}
 const night=row.querySelector('[data-bev-out="overnight"]'),keeper=BEV().roleText(BEV().rolesOf(bevRecord(bevAddDays(date,-1))).storekeeper);if(night&&!bad&&m.prevNight!==null)night.title=`تحویل شب قبل: ${F(m.prevNight,0)}${keeper?` — انباردار: ${keeper}`:''}`;bevTotals()}
function bevTotals(){for(const [k,cls] of [['daily',bevCls],['overnight',bevClsNight]]){const cells=[...document.querySelectorAll(`[data-bev-out="${k}"]`)].map(c=>c.dataset.v).filter(t=>t!==undefined&&t!==''),sum=cells.reduce((s,t)=>s+Number(t),0),c=document.querySelector(`[data-bev-total="${k}"]`);if(c){c.textContent=cells.length?bevFmt(sum):'—';c.className=cls(sum)}}}
function bevHydrate(){document.querySelectorAll('[data-bev-index]').forEach(r=>bevRowHint(r.dataset.bevIndex));window.RayoJalali?.mark?.()}
// Keeps the in-memory inventory state in step with a verified server document (only the beverage collections change).
function bevSync(doc){const v=inv();if(!v||!doc)return;v.beverageDailyControls=clone(A(doc.beverageDailyControls));v.changeLog=clone(A(doc.changeLog))}
// Report filters redraw only the report card so a half-filled entry form above it is kept.
function bevReportChanged(){if(document.querySelector('.v1012-bev-report'))bevRefreshReport();else renderView()}
function bevRefreshReport(){const card=document.querySelector('.v1012-bev-report');if(card&&bevItems().length){card.outerHTML=bevReport();window.RayoJalali?.mark?.()}}
async function bevSave(){if(ui.bevSaving)return;const status=document.getElementById('v1012BevStatus'),fields=document.getElementById('v1012BevFields'),R=BEV(),say=(m,e)=>{if(status)status.textContent=m;toast(m,e)};let edits=[],date='';
 try{date=R.normDate(document.getElementById('v1012BevDate')?.value);if(!date)throw Error('تاریخ شمسی معتبر وارد کنید');if(date>bevToday())throw Error('تاریخ فرم نمی‌تواند بعد از امروز باشد');
  const base=ui.bevBase;if(!base||base.date!==date)throw Error('فرم این تاریخ بارگذاری نشده است؛ تاریخ را دوباره انتخاب کنید');
  const errs=[];bevItems().forEach((it,i)=>{const r=R.read(bevRowRaw(i));if(r.errors.length)errs.push(`«${it.name}»: ${r.errors.join('، ')}`);const old=base.lines[it.id]||{fp:'',line:null};if(R.changedFields(old.line,r.values).length)edits.push({it,values:r.values,old})});
  if(errs.length)throw Error(errs.join('؛ '));
  const roles=bevReadRoles(base.roles);
  if(!edits.length&&!roles)throw Error('تغییری برای ذخیره وجود ندارد');
  const edited=edits.filter(x=>x.old.line);if(edited.length&&!confirm(edited.length===1?R.EDIT_CONFIRM:`قبلاً اطلاعات این نوشیدنی‌ها را ثبت کرده‌اید: ${edited.map(x=>x.it.name).join('، ')}. مطمئن هستید می‌خواهید تغییرشان دهید؟`)){if(status)status.textContent='ذخیره لغو شد؛ مقادیر فرم حفظ شده است.';return}
  ui.bevSaving=true;if(fields)fields.disabled=true;if(status)status.textContent='در حال ذخیره…';
  const doc=await RAYO_API_GATEWAY.loadModule('inventory'),at=now(),who={type:'admin',personnelId:'',name:actor()},recordId=`BEV-${newRequestId()}`,conflicts=[];
  for(const [n,x] of edits.entries()){try{R.applyEdit(doc,{date,item:x.it,values:x.values,actor:who,at,baseline:x.old.fp,recordId,roles:n===0?roles:undefined})}catch(e){if(e.code!=='bev_conflict')throw e;conflicts.push(x.it.name);base.lines[x.it.id]={fp:R.fingerprint(e.current),line:e.current}}}
  if(conflicts.length)throw Error(`اطلاعات ${conflicts.join('، ')} پس از بارگذاری فرم توسط کاربر دیگری تغییر کرده است. مقادیر فرم حفظ شد؛ برای جایگزینی، دوباره «ذخیره» را بزنید.`);
  // Only the people changed: apply them through an unchanged line so the record (if new) is created the same way.
  if(!edits.length&&roles){const it=bevItems()[0],cur=R.lineOf(R.recordOf(doc,date),it.id);R.applyEdit(doc,{date,item:it,values:R.formValues(cur),actor:who,at,baseline:R.fingerprint(cur),recordId,roles})}
  let checked=null;try{checked=(await RAYO_API_GATEWAY.saveModule('inventory',doc))?.checked||null}catch(e){if(!unknownSave(e))throw e;checked=await RAYO_API_GATEWAY.loadModule('inventory').catch(()=>null);if(!checked)throw e}
  if(!checked)checked=await RAYO_API_GATEWAY.loadModule('inventory');
  if(!edits.every(x=>R.savedMatches(checked,date,x.it.id,x.values))||(roles&&!R.rolesMatch(checked,date,roles)))throw Error('ذخیره روی سرور تأیید نشد؛ مقادیر فرم حفظ شد. دوباره تلاش کنید.');
  bevSync(checked);toast(`کنترل نوشابه ${date} ذخیره شد`);ui.bevDate=date;if(bevModalOpen())closeModal();renderView()}
 catch(e){say(e.message||'ذخیره انجام نشد؛ مقادیر فرم حفظ شد',true)}
 finally{ui.bevSaving=false;if(fields)fields.disabled=false}}
async function bevVoid(){const date=ui.bevDate||bevToday(),reason=bevRecord(date)?S(prompt('علت ابطال فرم این تاریخ (سابقه حذف نمی‌شود):')||''):'';if(!reason)return;
 try{const doc=await RAYO_API_GATEWAY.loadModule('inventory'),rec=BEV().recordOf(doc,date);if(!rec)throw Error('فرم این تاریخ روی سرور پیدا نشد');Object.assign(rec,{status:'void',voidReason:reason,voidedAt:now(),voidedBy:actor()});doc.changeLog=A(doc.changeLog);doc.changeLog.push({at:now(),action:'ابطال فرم کنترل روزانه نوشیدنی',actor:actor(),entityId:rec.id,date});const checked=(await RAYO_API_GATEWAY.saveModule('inventory',doc))?.checked||doc;if(A(checked.beverageDailyControls).find(x=>x.id===rec.id)?.status!=='void')throw Error('ابطال روی سرور تأیید نشد');bevSync(checked);toast('فرم باطل شد');renderView()}catch(e){toast(e.message||'ابطال انجام نشد',true)}}
function bevSettings(){const selected=new Set(bevItemIds()),rows=ingredients().slice().sort((a,b)=>(selected.has(b.id)-selected.has(a.id))||S(a.name).localeCompare(S(b.name),'fa'));RayoInventoryV10.openModal('اقلام کنترل روزانه نوشیدنی',`<p class="hint">نوشابه‌ها و آب‌معدنی‌هایی را که هر روز در یخچال‌های سالن شمارش می‌شوند انتخاب کنید. ترتیب فرم چاپی، ترتیب همین فهرست پس از ذخیره است.</p><input placeholder="جست‌وجوی نام یا کد" oninput="RayoInventoryV1012.bevSettingsFilter(this.value)" style="width:100%;margin-bottom:8px"><div style="max-height:55vh;overflow:auto">${rows.map(i=>`<label class="inline-check" data-bev-opt data-search="${E(norm(`${i.name} ${i.code||''} ${i.category||''}`))}" style="display:flex;gap:8px;padding:5px 0"><input type="checkbox" data-bev-pick="${E(i.id)}" ${selected.has(i.id)?'checked':''}> ${E(i.name)} <small class="muted">${E(i.code||'')} ${E(i.category||'')}</small></label>`).join('')}</div>`,`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="RayoInventoryV1012.bevSaveSettings()">ذخیره</button>`)}
function bevSettingsFilter(q){q=norm(q);document.querySelectorAll('[data-bev-opt]').forEach(r=>{r.style.display=!q||r.dataset.search.includes(q)?'flex':'none'})}
async function bevSaveSettings(){const v=inv(),before=clone(v),old=bevItemIds(),picked=[...document.querySelectorAll('[data-bev-pick]:checked')].map(x=>x.dataset.bevPick),itemIds=[...old.filter(id=>picked.includes(id)),...picked.filter(id=>!old.includes(id))];v.settings=v.settings||{};v.settings.beverageControl={...(v.settings.beverageControl||{}),itemIds,updatedAt:now(),updatedBy:actor()};v.changeLog=A(v.changeLog);v.changeLog.push({at:now(),action:'تنظیم اقلام کنترل روزانه نوشیدنی',actor:actor()});try{await RAYO_API_GATEWAY.saveModule('inventory',v);closeModal();toast('اقلام کنترل نوشیدنی ذخیره شد');renderView()}catch(e){Object.keys(v).forEach(k=>delete v[k]);Object.assign(v,before);toast(e.message||'ذخیره تنظیمات انجام نشد',true)}}
function bevRange(){const to=ui.bevTo||bevToday(),from=ui.bevFrom||bevAddDays(to,-29),days=[];let d=from;for(let n=0;n<370&&d&&d<=to;n++){days.push(d);d=bevAddDays(d,1)}return{from,to,days}}
// Two lines on one axis, both in units with "positive = loss": day variance (net, + shortage) and night variance
// (− overnight net, + stock lost overnight). Missing days break the lines; the zero line is emphasised.
function bevChart(points,title){const W=720,H=230,pad={t:16,r:12,b:30,l:48},has=p=>p.m&&!p.m.empty,vals=points.filter(has).flatMap(p=>[p.m.net,...(p.m.overnightKnown?[p.m.nightLoss]:[])]),hi=Math.max(1,...vals),lo=Math.min(-1,...vals),iw=W-pad.l-pad.r,ih=H-pad.t-pad.b,step=points.length>1?iw/(points.length-1):0,x=i=>pad.l+(points.length>1?i*step:iw/2),y=v=>pad.t+(hi-v)/(hi-lo)*ih,label=Math.max(1,Math.ceil(points.length/8));
 const series=(val,ok)=>{const segs=[];let cur=[];points.forEach((p,i)=>{if(ok(p))cur.push(`${x(i).toFixed(1)},${y(val(p)).toFixed(1)}`);else{if(cur.length)segs.push(cur);cur=[]}});if(cur.length)segs.push(cur);return segs},day=series(p=>p.m.net,has),night=series(p=>p.m.nightLoss,p=>has(p)&&p.m.overnightKnown);
 ui.bevPoints=points;const col=points.length>1?step:iw;
 return `<div class="v1012-bev-chart-wrap"><svg class="v1012-bev-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${E(title)}" onmouseleave="RayoInventoryV1012.bevHover(-1)">
 <line x1="${pad.l}" x2="${W-pad.r}" y1="${y(hi)}" y2="${y(hi)}" class="grid"/><line x1="${pad.l}" x2="${W-pad.r}" y1="${y(lo)}" y2="${y(lo)}" class="grid"/><line x1="${pad.l}" x2="${W-pad.r}" y1="${y(0)}" y2="${y(0)}" class="axis"/>
 <text x="${pad.l-8}" y="${y(hi)+4}" text-anchor="end">${bevFmt(hi)}</text><text x="${pad.l-8}" y="${y(0)+4}" text-anchor="end">۰</text><text x="${pad.l-8}" y="${y(lo)+4}" text-anchor="end">${bevFmt(lo)}</text>
 ${points.map((p,i)=>i%label===0||i===points.length-1?`<text x="${x(i)}" y="${H-8}" text-anchor="middle">${E(p.date.slice(5))}</text>`:'').join('')}
 <line id="v1012BevCross" class="cross" x1="0" x2="0" y1="${pad.t}" y2="${pad.t+ih}" visibility="hidden"/>
 ${day.map(s=>s.length>1?`<polyline class="line" points="${s.join(' ')}"/>`:'').join('')}${night.map(s=>s.length>1?`<polyline class="line night" points="${s.join(' ')}"/>`:'').join('')}
 ${points.map((p,i)=>has(p)?`<circle class="dot" cx="${x(i)}" cy="${y(p.m.net)}" r="4"/>${p.m.overnightKnown?`<circle class="dot night" cx="${x(i)}" cy="${y(p.m.nightLoss)}" r="4"/>`:''}`:`<line class="missing" x1="${x(i)}" x2="${x(i)}" y1="${y(0)-3}" y2="${y(0)+3}"/>`).join('')}
 ${points.map((p,i)=>`<rect class="hit" x="${(x(i)-col/2).toFixed(1)}" y="${pad.t}" width="${col.toFixed(1)}" height="${ih}" onmouseenter="RayoInventoryV1012.bevHover(${i})" onclick="RayoInventoryV1012.bevHover(${i})"><title>${E(bevTip(p))}</title></rect>`).join('')}
 </svg><div id="v1012BevTip" class="v1012-bev-tip" hidden></div></div>`}
function bevTip(p){if(!p.m||p.m.empty)return `${p.date}: فرم ثبت نشده`;const keeper=BEV().roleText(BEV().rolesOf(bevRecord(bevAddDays(p.date,-1))).storekeeper);return `${p.date} — مغایرت روز ${bevFmt(p.m.net)} (کسری ${F(p.m.shortage,0)} | اضافه ${F(p.m.surplus,0)})${p.m.overnightKnown?` | مغایرت شب ${bevFmt(p.m.nightLoss)}${keeper?` — انباردار: ${keeper}`:''}`:''} | فروش ${F(p.m.sales,0)}${p.m.incomplete?` | ${F(p.m.incomplete,0)} ردیف ناقص`:''}`}
function bevHover(i){const tip=document.getElementById('v1012BevTip'),cross=document.getElementById('v1012BevCross'),p=A(ui.bevPoints)[i];if(!tip||!cross)return;if(!p){tip.hidden=true;cross.setAttribute('visibility','hidden');return}const svg=cross.ownerSVGElement,W=720,pad=48,n=ui.bevPoints.length,cx=n>1?pad+i*(W-pad-12)/(n-1):(W+pad-12)/2;cross.setAttribute('x1',cx);cross.setAttribute('x2',cx);cross.setAttribute('visibility','visible');tip.textContent=bevTip(p);tip.hidden=false;tip.style.left=`${Math.min(82,Math.max(18,cx/W*100))}%`;if(svg)svg.dataset.active=i}
// Months of the Jalali calendar for the monthly view (keys "YYYY/MM", newest first).
function bevMonthKey(d){return S(d).slice(0,7)}
function bevMonthLabel(k){const [y,m]=S(k).split('/');return `${BEV_MONTHS[+m-1]||m} ${Number(y).toLocaleString('fa-IR',{useGrouping:false})}`}
function bevMonthDays(k){const days=[];let d=`${k}/01`;for(let n=0;n<31&&d&&d.startsWith(k);n++){days.push(d);d=bevAddDays(d,1)}return days}
function bevMonths(n){const out=[];let k=bevMonthKey(bevToday());for(let i=0;i<n&&k;i++){out.push(k);k=bevMonthKey(bevAddDays(`${k}/01`,-1))}return out}
const bevUnits=v=>v?`<span class="v1012-negative">${F(v,0)}</span>`:'۰';
function bevStatsTable(stats,clickable){const rows=stats.per.filter(s=>s.total||s.sales||s.days).sort((a,b)=>b.total-a.total),t=stats.tot;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>نوشیدنی</th><th>فروش</th><th>مغایرت روز</th><th>مغایرت شب</th><th>جمع مغایرت</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${clickable?`<button type="button" class="btn btn-sm" onclick="RayoInventoryV1012.bevRangeSet('item','${E(s.it.id)}')">${E(s.it.name)}</button>`:E(s.it.name)}</td><td>${F(s.sales,0)}</td><td>${bevUnits(s.day)}<br><small class="muted">کسری ${F(s.dayShort,0)} | اضافه ${F(s.daySur,0)}</small></td><td>${bevUnits(s.night)}<br><small class="muted">کاهش ${F(s.nightDown,0)} | افزایش ${F(s.nightUp,0)}</small></td><td><b>${F(s.total,0)}</b></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ثبتی در این بازه نیست.</td></tr>'}</tbody><tfoot><tr><th>جمع</th><th>${F(t.sales,0)}</th><th>${F(t.day,0)}</th><th>${F(t.night,0)}</th><th>${F(t.total,0)}</th></tr></tfoot></table></div>`}
// Monthly view: one month in one place (per beverage, day/night split, one-line summary) and the trend of the last 12 months.
function bevMonthPane(scope){const months=bevMonths(12);if(!months.includes(ui.bevMonth))ui.bevMonth=months[0];const k=ui.bevMonth,stats=bevStats(bevMonthDays(k),scope),t=stats.tot,top=stats.per.filter(s=>s.total).sort((a,b)=>b.total-a.total),trend=months.map(m=>({m,t:bevStats(bevMonthDays(m),scope).tot}));
 return `<div class="toolbar"><div class="field"><label>ماه</label><select data-no-placeholder="1" onchange="RayoInventoryV1012.bevMonth(this.value)">${months.map(m=>`<option value="${E(m)}" ${m===k?'selected':''}>${E(bevMonthLabel(m))}</option>`).join('')}</select></div></div>
 <p class="hint">${t.daysDone?`در ${E(bevMonthLabel(k))} در مجموع <b>${F(t.total,0)}</b> نوشیدنی مغایرت داشتیم: <b>${F(t.day,0)}</b> مغایرت روز و <b>${F(t.night,0)}</b> مغایرت شب${top.length?` — ${top.map(s=>`${F(s.total,0)} ${E(s.it.name)}`).join('، ')}`:''}. (${F(t.daysDone,0)} روز ثبت‌شده)`:`برای ${E(bevMonthLabel(k))} فرمی ثبت نشده است.`}</p>
 ${bevStatsTable(stats,false)}
 <h3 style="margin:14px 0 6px">روند ماهانه</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>ماه</th><th>روز ثبت‌شده</th><th>مغایرت روز</th><th>مغایرت شب</th><th>جمع مغایرت</th><th></th></tr></thead><tbody>${trend.map(r=>`<tr><td>${E(bevMonthLabel(r.m))}</td><td>${F(r.t.daysDone,0)}</td><td>${F(r.t.day,0)}</td><td>${F(r.t.night,0)}</td><td><b>${F(r.t.total,0)}</b></td><td><button type="button" class="btn btn-sm" onclick="RayoInventoryV1012.bevMonth('${E(r.m)}')">مشاهده</button></td></tr>`).join('')}</tbody></table></div>`}
// Shared report card (inventory page and dashboard): range, beverage filter and three tabs — daily list / chart / monthly.
function bevReport(){const r=bevRange(),items=bevItems(),tabName=['chart','month'].includes(ui.bevTab)?ui.bevTab:'list',sel=items.find(i=>i.id===ui.bevItem),scope=sel?[sel]:items,points=r.days.map(date=>{const rec=bevRecord(date),m=rec?bevDayMetrics(rec,ui.bevItem):null;if(m&&!m.lines)m.empty=true;return{date,rec,m}}),done=points.filter(p=>p.m&&!p.m.empty),stats=bevStats(r.days,scope),t=stats.tot,keeper=date=>BEV().roleText(BEV().rolesOf(bevRecord(bevAddDays(date,-1))).storekeeper);
 const list=`<div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>فروش</th><th>مغایرت روز</th><th>مغایرت شب</th><th>انباردار شب قبل</th><th>وضعیت</th><th></th></tr></thead><tbody>${points.slice().reverse().map(p=>p.m&&!p.m.empty?`<tr><td>${E(p.date)}${p.rec.source==='staff'?'<br><small class="muted">ثبت پرسنل</small>':''}</td><td>${p.m.salesKnown?F(p.m.sales,0):'<span class="badge warn">وارد نشده</span>'}</td><td class="${bevCls(p.m.net)}"><b>${bevFmt(p.m.net)}</b><br><small class="muted">کسری ${F(p.m.shortage,0)} | اضافه ${F(p.m.surplus,0)}</small></td><td class="${bevClsNight(p.m.overnight)}">${p.m.overnightKnown?`<b>${bevFmt(p.m.overnight)}</b><br><small class="muted">کاهش ${F(p.m.nightDown,0)} | افزایش ${F(p.m.nightUp,0)}</small>`:'—'}</td><td>${E(keeper(p.date)||'—')}</td><td>${p.m.incomplete?`<span class="badge warn">${F(p.m.incomplete,0)} ردیف ناقص</span>`:!p.m.shortage&&!p.m.surplus&&!p.m.nightDown&&!p.m.nightUp?'<span class="badge success">بدون مغایرت</span>':'<span class="badge danger">بررسی شود</span>'}</td><td><button type="button" class="btn btn-sm" onclick="RayoInventoryV1012.bevDate('${E(p.date)}')">مشاهده / اصلاح</button></td></tr>`:`<tr><td>${E(p.date)}</td><td colspan="5" class="muted">${p.rec?'این نوشیدنی در فرم نیامده':'فرم ثبت نشده'}</td><td><button type="button" class="btn btn-sm" onclick="RayoInventoryV1012.bevDate('${E(p.date)}')">${p.rec?'مشاهده':'ثبت'}</button></td></tr>`).join('')}</tbody></table></div>${sel?'':`<h3 style="margin:14px 0 6px">خلاصه هر نوشیدنی در بازه</h3>${bevStatsTable(stats,true)}`}`;
 const chart=`<div class="v1012-bev-legend"><span><i class="line"></i>مغایرت روز (+ کسری)</span><span><i class="line night"></i>مغایرت شب (+ کاهش موجودی شبانه)</span><span><i class="missing"></i>بدون فرم</span></div>${bevChart(points,`نمودار مغایرت روز و شب ${sel?sel.name:'همه نوشیدنی‌ها'}`)}`;
 return `<div class="card v1012-bev-report"><div class="section-head"><div><h2>گزارش مغایرت نوشیدنی${sel?` — ${E(sel.name)}`:''}</h2><p class="muted">مانده مورد انتظار شب = (جمع صبح + ورودی روز) − (خروج غیر فروش + فروش)؛ مغایرت روز = مانده مورد انتظار − جمع شب (مثبت = کسری، منفی = اضافه). مغایرت شب = شمارش صبح − مانده‌ای که انباردار شب قبل تحویل گرفته (منفی = کاهش موجودی). جمع‌ها به عدد نوشیدنی‌اند (کسری + اضافه، کاهش + افزایش). ردیف دارای خانه خالی «ناقص» است و در مغایرت روز نمی‌آید.</p></div></div>
 <div class="toolbar">${tabName==='month'?'':`<div class="field"><label>از تاریخ</label><input data-jalali="1" value="${E(r.from)}" onchange="RayoInventoryV1012.bevRangeSet('from',this.value)"></div><div class="field"><label>تا تاریخ</label><input data-jalali="1" value="${E(r.to)}" onchange="RayoInventoryV1012.bevRangeSet('to',this.value)"></div>`}<div class="field"><label>نوشیدنی</label><select data-no-placeholder="1" onchange="RayoInventoryV1012.bevRangeSet('item',this.value)"><option value="">همه نوشیدنی‌ها (جمع)</option>${opts(items,ui.bevItem)}</select></div>${tabName==='month'?'':`<div class="v1012-actions" role="group" aria-label="بازه سریع">${[[7,'۷ روز'],[30,'۳۰ روز'],[90,'۹۰ روز']].map(([n,l])=>`<button type="button" class="btn btn-sm" onclick="RayoInventoryV1012.bevRangeSet('preset',${n})">${l}</button>`).join('')}</div>`}</div>
 ${tabName==='month'?'':`<div class="v1012-report-grid"><div class="card kpi"><div class="label">روزهای ثبت‌شده</div><div class="value">${F(done.length,0)} / ${F(points.length,0)}</div><div class="sub">${F(points.length-done.length,0)} روز بدون فرم</div></div><div class="card kpi"><div class="label">مغایرت روز</div><div class="value ${t.day?'v1012-negative':''}">${F(t.day,0)}</div><div class="sub">کسری ${F(t.dayShort,0)} | اضافه ${F(t.daySur,0)}</div></div><div class="card kpi"><div class="label">مغایرت شب</div><div class="value ${t.night?'v1012-negative':''}">${F(t.night,0)}</div><div class="sub">کاهش ${F(t.nightDown,0)} | افزایش ${F(t.nightUp,0)}</div></div><div class="card kpi"><div class="label">جمع مغایرت</div><div class="value ${t.total?'v1012-negative':''}">${F(t.total,0)}</div><div class="sub">عدد نوشیدنی — فروش دوره ${F(t.sales,0)}</div></div></div>`}
 <div class="v1012-tabs v1012-subtabs" role="tablist">${[['list','لیست روزانه'],['chart','نمودار مغایرت روز و شب'],['month','خلاصه ماهانه']].map(([k,l])=>`<a href="#" role="tab" aria-selected="${tabName===k}" class="${tabName===k?'active':''}" onclick="event.preventDefault();RayoInventoryV1012.bevTab('${k}')">${l}</a>`).join('')}</div>
 ${tabName==='chart'?chart:tabName==='month'?bevMonthPane(scope):list}</div>`}
function bevView(){setTimeout(bevHydrate,0);return bevEntry()+(bevItems().length?bevReport():'')}
function bevModalOpen(){return !!document.querySelector('#modalBody #v1012BevFields,#modalBody #rbcForm')}
function bevOpenModal(date){if(!window.RayoInventoryV10?.isReady?.())return toast('اطلاعات انبار هنوز آماده نیست؛ چند لحظه بعد دوباره بزنید',true);if(date)ui.bevDate=date;RayoInventoryV10.openModal(BEV_TITLE,bevEntry(true),'<button class="btn" onclick="closeModal()">بستن</button>');setTimeout(bevHydrate,0)}
function bevPrint(){const date=ui.bevDate||bevToday(),items=bevItems();if(!items.length)return toast('ابتدا اقلام کنترل نوشیدنی را انتخاب کنید',true);const w=window.open('','_blank','width=1000,height=700');if(!w)return toast('مرورگر پنجره پرینت را مسدود کرده است',true);const font=`${location.origin}/css/fonts/woff/IRANSansX-Regular.woff`,bold=`${location.origin}/css/fonts/woff/IRANSansX-Bold.woff`,cells=n=>'<td></td>'.repeat(n),roles=BEV().rolesOf(bevRecord(date)),prevKeeper=BEV().roleText(BEV().rolesOf(bevRecord(bevAddDays(date,-1))).storekeeper);
 w.document.write(`<!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><title>فرم کنترل روزانه فروش نوشابه ${E(date)}</title><style>@font-face{font-family:IRANSansX;src:url('${font}') format('woff')}@font-face{font-family:IRANSansX;src:url('${bold}') format('woff');font-weight:700}@page{size:A5 landscape;margin:6mm}*{box-sizing:border-box}body{font-family:IRANSansX,Tahoma,sans-serif;font-size:8pt;color:#000;margin:0}.top{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:2mm}h1{font-size:11pt;margin:0}.meta span{display:inline-block;min-width:32mm;border-bottom:1px solid #000;margin-inline-start:4mm}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #333;padding:1.3mm .6mm;text-align:center;height:6.2mm}th{background:#eee;font-size:7pt;font-weight:700}td.name{text-align:right;font-weight:700;width:24mm}td.ref{background:#f3f3f3}.g{border-inline-start:2px solid #000}.sign{display:grid;grid-template-columns:repeat(4,1fr);gap:3mm;margin-top:2.5mm}.sign div{border:1px solid #333;padding:1.2mm;font-size:7pt;min-height:12mm}.hint{font-size:6.8pt;margin-top:1.5mm;line-height:1.6}</style></head><body>
 <div class="top"><h1>فرم کنترل روزانه فروش نوشابه — یخچال سالن بالا و پایین</h1><div class="meta">تاریخ: <span>${E(date)}</span></div></div>
 <table><thead><tr><th rowspan="2" style="width:24mm">نوشیدنی</th><th rowspan="2" class="g">تحویل شب قبل</th><th colspan="2" class="g">شمارش صبح</th><th rowspan="2" class="g">ورودی روز</th><th rowspan="2" class="g">خروج غیر فروش</th><th colspan="2" class="g">مانده شب</th><th rowspan="2" class="g">فروش</th><th rowspan="2" class="g" style="width:30mm">علت خروج / علت مغایرت</th></tr><tr><th class="g">بالا</th><th>پایین</th><th class="g">بالا</th><th>پایین</th></tr></thead><tbody>${items.map(it=>{const pn=BEV().values(bevPrevLine(date,it.id)).night;return `<tr><td class="name">${E(it.name)}</td><td class="ref g">${pn===null?'':F(pn,0)}</td><td class="g"></td><td></td><td class="g"></td><td class="g"></td><td class="g"></td><td></td><td class="g"></td><td class="g"></td></tr>`}).join('')}${'<tr><td class="name"></td><td class="g"></td>'+cells(8)+'</tr>'}</tbody></table>
 <div class="sign"><div>شمارنده صبح (تحویل و تطبیق با تحویل شب قبل${prevKeeper?` — انباردار: ${E(prevKeeper)}`:''}):<br>${E(BEV().roleText(roles.morningCounter))||'نام و امضا / ساعت'}</div><div>شمارنده شب (شمارش نهایی):<br>${E(BEV().roleText(roles.nightCounter))||'نام و امضا / ساعت'}</div><div>انباردار (تحویل از شمارنده شب):<br>${E(BEV().roleText(roles.storekeeper))||'نام و امضا / ساعت'}</div><div>مغایرت و علت:<br></div></div>
 <div class="hint">خانه خالی یعنی «وارد نشده»؛ برای نبودِ کالا «۰» بنویسید. شمارش صبح با ستون «تحویل شب قبل» (مانده‌ای که انباردار از شمارنده شب تحویل گرفته) تطبیق داده شود؛ هر اختلاف مغایرت شبانه است و همان لحظه به سرپرست گزارش شود. ورودی روز = مجموع شارژ هر دو یخچال از انبار. خروج غیر فروش = پرسنلی، مهمان، شکسته/خراب، برگشت به انبار؛ علت آن نوشته شود. فروش روز از صندوق گرفته شود و آخرین عدد فرم است. جابه‌جایی بین دو یخچال ورود یا خروج نیست.</div>
 <script>setTimeout(()=>print(),400)<\/script></body></html>`);w.document.close()}
function bevDashboardCard(){const ready=!!window.RayoInventoryV10?.isReady?.(),buttons=`<div class="v1012-actions"><a class="btn" href="inventory.html?tab=count&sub=beverage">جزئیات</a></div>`;
 if(!ready)return `<div class="card v1012-quick-control"><div class="section-head"><div><h2>کنترل روزانه نوشیدنی و اقلام سرو</h2><p class="muted">در حال بارگذاری اطلاعات انبار…</p></div>${buttons}</div></div>`;
 const items=bevItems(),t=bevToday(),y=bevAddDays(t,-1),last=bevRecords().filter(x=>x.date<=t).sort((a,b)=>S(b.date).localeCompare(S(a.date)))[0],lm=last?bevDayMetrics(last):null,missing=Array.from({length:7},(_,i)=>bevAddDays(t,-1-i)).filter(d=>!bevRecord(d)).length,svc=window.__RAYO_ASSETS__?.isLoaded?.()?window.__RAYO_ASSETS__.serviceSummary():null,svcErr=window.__RAYO_ASSETS__?.loadError?.();
 if(!svc&&!svcErr&&window.__RAYO_ASSETS__?.ensureLoaded&&!ui.dashAssetsRequested){ui.dashAssetsRequested=true;Promise.resolve(window.__RAYO_ASSETS__.ensureLoaded(true)).then(()=>{if(currentView==='dashboard')(window.refreshDashboardSoon||renderView)()})}
 if(!ui.bevFrom&&!ui.bevTo&&!ui.bevRangeTouched){ui.bevFrom=bevAddDays(t,-6);ui.bevTo=t}
 setTimeout(()=>window.RayoJalali?.mark?.(),0);
 return `<div class="card v1012-quick-control"><div class="section-head"><div><h2>کنترل روزانه نوشیدنی و اقلام سرو</h2><p class="muted">ثبت سریع از روی فرم‌های کاغذی و هشدار کمبود.</p></div>${buttons}</div><div class="grid grid-4">
 <div class="kpi"><div class="label">آخرین فرم نوشیدنی</div><div class="value ${lm?bevCls(lm.net):''}">${lm?bevFmt(lm.net):'—'}</div><div class="sub">${last?`${E(last.date)} — کسری ${F(lm.shortage,0)} | اضافه ${F(lm.surplus,0)}${lm.incomplete?` | ${F(lm.incomplete,0)} ناقص`:''}`:items.length?'هنوز ثبت نشده':'اقلام تنظیم نشده'}</div></div>
 <div class="kpi"><div class="label">روز بدون فرم (۷ روز گذشته)</div><div class="value ${missing?'danger-text':''}">${F(missing,0)}</div><div class="sub">${bevRecord(y)?'فرم دیروز ثبت شده':'فرم دیروز ثبت نشده'}</div></div>
 <div class="kpi"><div class="label">اقلام سرو کمتر از حداقل</div><div class="value ${svc?.low.length?'danger-text':''}">${svc?F(svc.low.length,0):'—'}</div><div class="sub">${svc?(svc.low.slice(0,3).map(a=>E(a.name)).join('، ')||`از ${F(svc.items,0)} قلم ${E(svc.category||'')}`):svcErr?'بارگذاری اموال انجام نشد':'در حال بارگذاری…'}</div></div>
 <div class="kpi"><div class="label">شکستگی / مفقودی ۷ روز</div><div class="value">${svc?`${F(svc.breakage,0)} / ${F(svc.missing,0)}`:'—'}</div><div class="sub">${svc?(svc.lastCount?`آخرین شمارش ${E(svc.lastCount)}${svc.daysSinceCount>7?` <span class="badge warn">${F(svc.daysSinceCount,0)} روز پیش</span>`:''}`:'<span class="badge warn">شمارش ثبت نشده</span>'):''}</div></div></div></div>
 ${items.length?bevReport():''}`}
function installDashboard(){if(!['index.html',''].includes(file()))return;if(typeof views==='undefined'||!views.dashboard)return setTimeout(installDashboard,120);if(views.dashboard.__v1012bev)return;const old=views.dashboard,w=function(){const base=old(),card=bevDashboardCard(),marker='<!--dash-quick-end-->';return base.includes(marker)?base.replace(marker,()=>card):card+base};w.__v1012bev=true;views.dashboard=w;if(!window.RayoInventoryV10)return;RayoInventoryV10.ensure?.().then(ready=>{if(ready&&currentView==='dashboard')(window.refreshDashboardSoon||renderView)()})}
function supplierTabs(active){const rows=[['dashboard','داشبورد'],['suppliers','تأمین‌کنندگان'],['relations','اقلام هر تأمین‌کننده'],['invoices','فاکتورهای خرید'],['history','سوابق خرید'],['orderDesk','میز سفارش‌گذاری'],['orders','سفارش‌های ثبت‌شده'],['accounts','حساب و بدهی‌ها'],['payment','پرداخت‌ها'],['json','تنظیمات']];return `<div class="supplier-module-tabs">${rows.map(([k,l])=>k==='json'?`<a class="btn" href="settings.html?view=softwareSettings&section=purchase">${l}</a>`:`<button class="btn ${active===k?'btn-primary active':''}" onclick="RayoInventoryV1012.supplierTab('${k}')">${l}</button>`).join('')}</div>`}
function purchaseHistory(){const rows=A(inv()?.purchaseInvoices).filter(x=>x.status!=='void').sort((a,b)=>S(b.date).localeCompare(S(a.date))).slice(0,500);return pageHead('سوابق خرید','سوابق مالی خرید؛ ورود فیزیکی فقط در انبارداری ثبت می‌شود.')+supplierTabs('history')+`<div class="card"><div class="hint">این صفحه موجودی را ایجاد یا اصلاح نمی‌کند.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>شماره</th><th>تأمین‌کننده</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${E(x.date)}</td><td>${E(x.invoiceNumber||x.reference||'—')}</td><td>${E(A(suppliers()?.suppliers).find(s=>s.id===x.supplierId)?.name||'متفرقه')}</td><td>${M(x.totalToman||A(x.lines).reduce((a,l)=>a+N(l.quantity)*N(l.unitPrice),0))}</td><td>${E(x.paymentStatus||x.status||'ثبت‌شده')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">سابقه‌ای نیست.</td></tr>'}</tbody></table></div></div>`}
